local loaded_resources = false

local function should_preload(bank_name)
	if EMVSettings and EMVSettings.mhwilds_load_all_motbanks then return true end
	return bank_name:find("^motion/player/")
		or bank_name:find("^motion/enemy/")
		or bank_name:find("^motion/otomo/")
		or bank_name:find("^motion/npc/")
		or bank_name:find("^motion/facial/")
		or bank_name:find("^motion/guildcard/")
		or bank_name:find("^gamedesign/enemy/")
end

re.on_application_entry("BeginRendering", function()
	if loaded_resources or game_name ~= "mhwilds" or not RN or not RSCache then return end
	RSCache.motbank_resources = RSCache.motbank_resources or {}
	RN.motbank_resource_names = RN.motbank_resource_names or {}
	for i, bank_string in ipairs(motbanks) do
		local bank_name = bank_string:lower()
		RN.motbank_resource_names[#RN.motbank_resource_names + 1] = bank_name
		if should_preload(bank_name) then
			local bank = create_resource(bank_string, "via.motion.MotionBankResource")
			if bank then RSCache.motbank_resources[bank_name] = bank end
		end
	end
	loaded_resources = true
	log.info("[EMV] Monster Hunter Wilds motbank names registered: " .. tostring(#motbanks))
end)

local function finished()
	return loaded_resources
end

local function reset()
	loaded_resources = false
end

return {
	motbanks = motbanks,
	backgrounds = {},
	alt_names = {},
	finished = finished,
	reset = reset,
}
